SELECT *
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN
LIMIT 10;
-- 1. Dataset size
SELECT COUNT(*)
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN;

-- 2. Target distribution
SELECT
    TARGET,
    COUNT(*) AS COUNT
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN
GROUP BY TARGET;
-- 3. Inspect important varibles 
SELECT
    SK_ID_CURR,
    TARGET,
    AMT_INCOME_TOTAL,
    AMT_CREDIT,
    AMT_ANNUITY
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN
LIMIT 10;
-- 4. Overall financial characteristics
SELECT
    AVG(AMT_INCOME_TOTAL) AS AVG_INCOME,
    AVG(AMT_CREDIT) AS AVG_CREDIT,
    AVG(AMT_ANNUITY) AS AVG_ANNUITY
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN;

-- 5. Financial characteristics by default status
SELECT
    TARGET,
    COUNT(*) AS APPLICATIONS,
    AVG(AMT_INCOME_TOTAL) AS AVG_INCOME,
    AVG(AMT_CREDIT) AS AVG_CREDIT,
    AVG(AMT_ANNUITY) AS AVG_ANNUITY,
FROM HOME_CREDIT.RAW.APPLICATION_TRAIN
GROUP BY TARGET
ORDER BY TARGET;

-- 6. Inspect all columns and data types
SELECT
    COLUMN_NAME,
    DATA_TYPE
FROM HOME_CREDIT.INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_SCHEMA = 'RAW'
  AND TABLE_NAME = 'APPLICATION_TRAIN'
ORDER BY ORDINAL_POSITION;

-- 7. Generate a query to rank columns by missing percentage

SELECT
    LISTAGG(
        'SELECT ''' || COLUMN_NAME || ''' AS COLUMN_NAME, ' ||
        'COUNT_IF("' || COLUMN_NAME || '" IS NULL) AS MISSING_COUNT, ' ||
        'ROUND(COUNT_IF("' || COLUMN_NAME || '" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT ' ||
        'FROM HOME_CREDIT.RAW.APPLICATION_TRAIN',
        ' UNION ALL '
    ) WITHIN GROUP (ORDER BY ORDINAL_POSITION) ||
    ' ORDER BY MISSING_PERCENT DESC;'
    AS GENERATED_QUERY
FROM HOME_CREDIT.INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_SCHEMA = 'RAW'
  AND TABLE_NAME = 'APPLICATION_TRAIN';

SELECT 'SK_ID_CURR' AS COLUMN_NAME, COUNT_IF("SK_ID_CURR" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("SK_ID_CURR" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'TARGET' AS COLUMN_NAME, COUNT_IF("TARGET" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("TARGET" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'NAME_CONTRACT_TYPE' AS COLUMN_NAME, COUNT_IF("NAME_CONTRACT_TYPE" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("NAME_CONTRACT_TYPE" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'CODE_GENDER' AS COLUMN_NAME, COUNT_IF("CODE_GENDER" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("CODE_GENDER" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'FLAG_OWN_CAR' AS COLUMN_NAME, COUNT_IF("FLAG_OWN_CAR" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("FLAG_OWN_CAR" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'FLAG_OWN_REALTY' AS COLUMN_NAME, COUNT_IF("FLAG_OWN_REALTY" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("FLAG_OWN_REALTY" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'CNT_CHILDREN' AS COLUMN_NAME, COUNT_IF("CNT_CHILDREN" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("CNT_CHILDREN" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'AMT_INCOME_TOTAL' AS COLUMN_NAME, COUNT_IF("AMT_INCOME_TOTAL" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("AMT_INCOME_TOTAL" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'AMT_CREDIT' AS COLUMN_NAME, COUNT_IF("AMT_CREDIT" IS NULL) AS MISSING_COUNT, ROUND(COUNT_IF("AMT_CREDIT" IS NULL) * 100.0 / COUNT(*), 2) AS MISSING_PERCENT FROM HOME_CREDIT.RAW.APPLICATION_TRAIN UNION ALL SELECT 'AMT_ANNUITY' AS